package com.capitalone.chargeback;

import java.util.*;import java.util.stream.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import io.camunda.client.*;
@Service class DisputeService {
 private final TransactionRepository tx; private final DisputeRepository disputes; private final Optional<CamundaClient> client; @Value("${app.workflow-enabled:false}") boolean workflow; @Value("${app.merchant-timeout:P3D}") String merchantTimeout;
 DisputeService(TransactionRepository t,DisputeRepository d,org.springframework.beans.factory.ObjectProvider<CamundaClient> c){tx=t;disputes=d;client=Optional.ofNullable(c.getIfAvailable());}
 @Transactional DisputeCase create(CreateDisputeRequest request){if(request==null||request.items()==null||request.items().isEmpty())throw new IllegalArgumentException("Select at least one transaction"); var c=new DisputeCase();c.customerId=request.customerId()==null?"customer-001":request.customerId(); Set<String> seen=new HashSet<>(); for(var line:request.items()){if(line.reason()==null||line.reason().isBlank())throw new IllegalArgumentException("A dispute reason is required");if(!seen.add(line.transactionId()))throw new IllegalArgumentException("Duplicate transaction in claim");var t=tx.findById(line.transactionId()).orElseThrow(()->new IllegalArgumentException("Transaction not found: "+line.transactionId()));if(!t.customerId.equals(c.customerId))throw new IllegalArgumentException("Transaction does not belong to customer");if(t.disputed)throw new IllegalArgumentException("Transaction already disputed: "+t.id);t.disputed=true;var i=new DisputeItem();i.transactionId=t.id;i.merchant=t.merchant;i.amount=t.amount;i.reason=line.reason();c.items.add(i);} c=disputes.save(c); if(workflow&&client.isPresent()){var saved=c; var event=client.get().newCreateInstanceCommand().bpmnProcessId("chargeback-dispute").latestVersion().variables(Map.of("caseId",saved.id,"merchantTimeout",merchantTimeout,"transactions",saved.items.stream().map(i->Map.of("itemId",i.id,"transactionId",i.transactionId,"amount",i.amount,"reason",i.reason)).toList())).send().join();saved.workflowInstanceId=String.valueOf(event.getProcessInstanceKey());} return c; }
 List<DisputeCase> all(){return disputes.findAll();} DisputeCase one(String id){return disputes.findById(id).orElseThrow(()->new NoSuchElementException("Dispute not found"));}
 DashboardSummary summary(){var all=all();return new DashboardSummary(all.stream().filter(c->!"COMPLETED".equals(c.status)).count(),all.stream().flatMap(c->c.items.stream()).filter(i->"APPROVED".equals(i.decision)).count(),all.stream().flatMap(c->c.items.stream()).filter(i->"REJECTED".equals(i.decision)).count(),all.stream().flatMap(c->c.items.stream()).filter(i->i.amount.intValue()>=4000).count());}
}
